import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import Editor from '@monaco-editor/react';
import { Terminal } from 'xterm';
import 'xterm/css/xterm.css';
import '../css/Projectpage.css';

export default function ProjectPage() {
    const navigate = useNavigate();
    const [files, setFiles] = useState([]);
    const [activeIndex, setActiveIndex] = useState(null);
    const termRef = useRef(null);
    const xtermRef = useRef(null);
    const editorRef = useRef(null);

    useEffect(() => {
        // Initialize terminal
        xtermRef.current = new Terminal({ convertEol: true });
        xtermRef.current.open(termRef.current);
        xtermRef.current.writeln('Ready to create project...');

        // Override console.log to redirect to xterm
        const originalLog = console.log;
        console.log = (...args) => {
            xtermRef.current.writeln(args.join(' '));
            originalLog(...args);
        };

        return () => {
            console.log = originalLog;
        };
    }, []);

    const handleBack = () => navigate(-1);

    // Create new file in project
    const handleNewFile = () => {
        const fileName = prompt('새 파일 이름을 입력하세요 (확장자 포함):');
        if (!fileName) return;
        if (files.find(f => f.name === fileName)) {
            alert('이미 동일한 이름의 파일이 존재합니다.');
            return;
        }
        setFiles(prev => {
            const newFiles = [...prev, { name: fileName, content: '' }];
            setActiveIndex(newFiles.length - 1);
            return newFiles;
        });
    };

    const handleFileDrop = e => {
        e.preventDefault();
        const droppedFiles = Array.from(e.dataTransfer.files);
        droppedFiles.forEach(file => {
            const reader = new FileReader();
            reader.onload = () => {
                setFiles(prev => {
                    const newFiles = [...prev, { name: file.name, content: reader.result }];
                    setActiveIndex(newFiles.length - 1);
                    return newFiles;
                });
            };
            reader.readAsText(file);
        });
    };

    const handleDragOver = e => {
        e.preventDefault();
    };

    const handleSelectFile = index => {
        setActiveIndex(index);
    };

    const handleEditorDidMount = (editor) => {
        editorRef.current = editor;
    };

    // Execute code from editor
    const runCode = () => {
        if (!editorRef.current) return;
        const code = editorRef.current.getValue();
        xtermRef.current.clear();
        try {
            // eslint-disable-next-line no-eval
            eval(code);
        } catch (err) {
            xtermRef.current.writeln(err.toString());
        }
    };

    return (
        <div className="ide-container">
            <header className="ide-header">
                <button className="ide-back-btn" onClick={handleBack}>&larr; 뒤로</button>
                <h2>새 프로젝트 생성</h2>
                <button className="new-file-btn" onClick={handleNewFile}>새 파일</button>
            </header>

            <div className="ide-body">
                <aside
                    className="file-tree"
                    onDrop={handleFileDrop}
                    onDragOver={handleDragOver}
                >
                    {files.map((file, idx) => (
                        <div
                            key={idx}
                            className={`file-item ${activeIndex === idx ? 'active' : ''}`}
                            onClick={() => handleSelectFile(idx)}
                        >
                            {file.name}
                        </div>
                    ))}
                    <div className="file-item placeholder">파일을 여기에 드래그하세요</div>
                </aside>

                <div className="editor-pane">
                    <Editor
                        height="100%"
                        language="javascript"
                        value={files[activeIndex]?.content || ''}
                        onMount={handleEditorDidMount}
                        onChange={value => {
                            if (activeIndex === null) return;
                            setFiles(prev => {
                                const updated = [...prev];
                                updated[activeIndex] = { ...updated[activeIndex], content: value || '' };
                                return updated;
                            });
                        }}
                        theme="vs-dark"
                    />
                    <button className="run-btn" onClick={runCode}>Run</button>
                </div>

                <div className="console-pane" ref={termRef}></div>
            </div>
        </div>
    );
}
